from solution import fib

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def _ref(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a


def test_spec_examples():
    assert fib(10) == 55
    assert fib(1) == 1
    assert fib(8) == 21


def test_fib_zero_is_zero():
    assert fib(0) == 0


def test_fib_base_cases_one_two():
    assert fib(1) == 1
    assert fib(2) == 1


def test_fib_returns_int_for_valid_inputs():
    for n in [0, 1, 2, 3, 5, 8, 10, 20]:
        r = fib(n)
        assert isinstance(r, int), f"fib({n}) should be int, got {type(r)}"


@given(st.integers(min_value=0, max_value=25))
def test_reference_model_equivalence(n):
    assert fib(n) == _ref(n)


@given(st.integers(min_value=2, max_value=25))
def test_recurrence_relation(n):
    assert fib(n) == fib(n - 1) + fib(n - 2)


@given(st.integers(min_value=0, max_value=25))
def test_monotonic_nondecreasing(n):
    # 0, 1, 1, 2, 3, 5, ... is non-decreasing
    assert fib(n + 1) >= fib(n)


@given(st.integers(min_value=0, max_value=20))
def test_sum_identity(n):
    # sum_{i=0..n} F(i) == F(n+2) - 1
    assert sum(fib(i) for i in range(n + 1)) == fib(n + 2) - 1


@given(st.integers(min_value=0, max_value=20))
def test_doubling_identity_consistency(n):
    # F(2n) == F(n) * (2*F(n+1) - F(n))
    assert fib(2 * n) == fib(n) * (2 * fib(n + 1) - fib(n))
